window.docContents[183].resolve({"/Basic-Types/Strings/#string-ffi":{"contents":"The representation of strings in C. See the description of run-time Strings for more details.\n\nReturns true if o is a string, or false otherwise.\n\nPerforms a runtime check that o is indeed a string. If o is not a string, an assertion fails.\n\n\n\n","context":"Lean 中文参考手册\u0009Basic Types\u0009Strings","header":"20.8.5. FFI","id":"/Basic-Types/Strings/#string-ffi"},"/IO/Tasks-and-Threads/#Lean-__________________--IO--Tasks-and-Threads--Task-Results":{"contents":"Blocks the current thread until the given task has finished execution, and then returns the result\nof the task. If the current thread is itself executing a (non-dedicated) task, the maximum\nthreadpool size is temporarily increased by one while waiting so as to ensure the process cannot\nbe deadlocked by threadpool starvation. Note that when the current thread is unblocked, more tasks\nthan the configured threadpool size may temporarily be running at the same time until sufficiently\nmany tasks have finished.Task.map and Task.bind should be preferred over Task.get for setting up task dependencies\nwhere possible as they do not require temporarily growing the threadpool in this way. In\nparticular, calling Task.get in a task continuation with (sync := true) will panic as the\ncontinuation is decidedly not \"cheap\" in this case and deadlocks may otherwise occur. The\nwaited-upon task should instead be returned and unwrapped using Task.bind/IO.bindTask.\n\nWaits for the task to finish, then returns its result.\n\nWaits until any of the tasks in the list has finished, then returns its result.\n\n","context":"Lean 中文参考手册\u0009IO\u0009Tasks and Threads","header":"21.11.2. Task Results","id":"/IO/Tasks-and-Threads/#Lean-__________________--IO--Tasks-and-Threads--Task-Results"},"/Source Files and Modules/#comments":{"contents":"注释是文件中虽然不是空白符，但被视为空白的部分。\nLean 提供两种注释语法：\n\n 行注释\n\n当 -- 不作为其他词法单元一部分出现时，表示行注释。该标记后的所有内容直到行尾都会被视为空白字符。\n\n 块注释\n\n当 /- 不作为其他词法单元一部分，且后面不是 - 字符时，表示块注释的开始。\n  块注释会一直持续到出现 -/ 终止为止。\n  块注释允许嵌套；仅在所有内部嵌套的 /- 都被匹配的 -/ 终止后，最外层才算结束。\n\n\n\n/-- 与 /-! 用于开始 文档注释 ，它们同样以 -/ 结束，并允许嵌套块注释。\n尽管文档注释看起来与普通注释类似，但在语法上它们属于不同类别；它们能出现的位置由 Lean 的语法决定。\n\n","context":"Lean 中文参考手册\u0009源文件与模块\u0009具体语法","header":"5.2.2. 注释","id":"/Source Files and Modules/#comments"},"/Terms/#terms":{"contents":"Terms are the principal means of writing mathematics and programs in Lean.\nThe elaborator translates them to Lean's minimal core language, which is then checked by the kernel and compiled for execution.\nThe syntax of terms is arbitrarily extensible; this chapter documents the term syntax that Lean provides out-of-the-box.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Lean 中文参考手册","header":"13. Terms","id":"/Terms/#terms"},"/releases/v4.26.0/#Lean-__________________--Release-Notes--Lean-4___26___0-_LPAR_2025-12-13_RPAR_--Highlights":{"contents":"\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Lean 中文参考手册\u0009Release Notes\u0009Lean 4.26.0 (2025-12-13)","header":"Highlights","id":"/releases/v4.26.0/#Lean-__________________--Release-Notes--Lean-4___26___0-_LPAR_2025-12-13_RPAR_--Highlights"},"/releases/v4.30.0/#Lean-__________________--Release-Notes--Lean-4___30___0-_LPAR_2026-05-26_RPAR_--Highlights--Library-Highlights--HTTP-Library":{"contents":"#12126, #12127, #12128, and #12144 introduce core HTTP data types: Request, Response, Status, Version, Method, Headers, URI, and streaming Body. This is the foundation of a standard HTTP library in Lean.\n\n","context":"Lean 中文参考手册\u0009Release Notes\u0009Lean 4.30.0 (2026-05-26)\u0009Highlights\u0009Library Highlights","header":"HTTP Library","id":"/releases/v4.30.0/#Lean-__________________--Release-Notes--Lean-4___30___0-_LPAR_2026-05-26_RPAR_--Highlights--Library-Highlights--HTTP-Library"}});